#!/usr/bin/env python3
"""Concurrency harness for the reportd worker pool.

Drives src/worker.py's Pool with the same handoff/claim protocol the
rollup workers use, on a single driver thread, and asserts the
invariants the pool is responsible for:

  * every submitted job is claimed exactly once;
  * handoff never returns a job to a worker that already holds one
    (the job it would return gets requeued and must be claimed by
    someone else);
  * when the queue is empty, handoff and claim both return None
    without blocking.

Running the protocol single-threaded keeps failures deterministic: a
broken pool fails every run on the same invariant, instead of flaking
on whichever worker happens to grab a lock first.
"""
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.dirname(
    os.path.abspath(__file__))), "src"))

from worker import Pool

WORKERS = ["worker-%d" % i for i in range(16)]
N_JOBS = 64


def run_protocol(pool):
    jobs = ["job-%03d" % i for i in range(N_JOBS)]
    for j in jobs:
        pool.submit(j)

    held = {w: None for w in WORKERS}
    claimed = {}

    # Phase 1: hand the queue out. While a worker is busy, its handoff
    # must not also return it a second job.
    while True:
        progress = False
        for w in WORKERS:
            report = pool.handoff(w, "report-from-%s" % w)
            if report is None:
                continue
            if held[w] is not None:
                # Regression: handoff handed out a second job while this
                # worker still holds one. Return it to the pool.
                pool.submit(report)
                raise AssertionError(
                    "worker %s held job %r and handoff returned %r "
                    "(a worker holds two jobs at once)" % (w, held[w], report))
            held[w] = report
            progress = True
        if not progress:
            break

    # Phase 2: idle workers hand off reports and claim what their
    # handoff returned (the requeued second jobs), then the rest of the
    # queue.
    while True:
        progress = False
        for w in WORKERS:
            if held[w] is None:
                report = pool.handoff(w, "report-from-%s" % w)
                if report is not None:
                    held[w] = report
                    progress = True
        for w in WORKERS:
            if held[w] is not None:
                claimed[held[w]] = claimed.get(held[w], 0) + 1
                pool.handoff(w, "result-for-%s" % held[w])
                held[w] = None
                progress = True
        if not progress:
            break

    # Phase 3: everything is drained; the empty-queue paths must be
    # non-blocking and return None.
    for w in WORKERS:
        if pool.handoff(w, "final-from-%s" % w) is not None:
            raise AssertionError("handoff returned a job on an empty queue")
        if pool.claim(w) is not None:
            raise AssertionError("claim returned a job on an empty queue")

    return sorted(claimed), sorted(jobs)


def test_all():
    pool = Pool()
    got, want = run_protocol(pool)
    missing = [j for j in want if j not in got]
    dupes = sorted(j for j, c in _count(got).items() if c > 1)
    if missing or dupes:
        raise AssertionError("jobs lost or double-claimed: missing=%s dupes=%s"
                             % (missing, dupes))
    print("pool stress: 16 workers, %d jobs - no hang, no lost jobs" % N_JOBS)


def _count(seq):
    out = {}
    for item in seq:
        out[item] = out.get(item, 0) + 1
    return out


if __name__ == "__main__":
    try:
        test_all()
    except Exception as exc:
        print("POOL FAIL: %s" % exc)
        sys.exit(1)
